import { vesselClass, classesForPort, portByCode } from "@harbor/dispatch/ports/registry";

// Check 1: vesselClass("Neopanamax") returns correct specs
const neoClass = vesselClass("Neopanamax");
console.log("Neopanamax class:", neoClass);

// Check 2: classesForPort includes it for Singapore
const singapore = portByCode("SGSIN");
const singaporeClasses = classesForPort(singapore);
const inSingapore = singaporeClasses.some(c => c.name === "Neopanamax");
console.log("Available in Singapore:", inSingapore);

// Check 3: classesForPort does not include it for Gdynia
const gdynia = portByCode("PLGDY");
const gdyniaClasses = classesForPort(gdynia);
const inGdynia = gdyniaClasses.some(c => c.name === "Neopanamax");
console.log("Available in Gdynia:", inGdynia);

// Show details
console.log("\nSingapore (max draft 16m):", singaporeClasses.map(c => c.name));
console.log("Gdynia (max draft 13m):", gdyniaClasses.map(c => c.name));
EOF
